using System.Collections.ObjectModel;
using System.Windows;
using RefaccionariaDesktop.Data;
using RefaccionariaDesktop.Models;
namespace RefaccionariaDesktop;
public partial class MainWindow:Window{
 readonly Database db=new();readonly ObservableCollection<CartLine> cart=new();
 public MainWindow(){InitializeComponent();ProductsGrid.ItemsSource=db.GetProducts();CartGrid.ItemsSource=cart;RefreshStatus();}
 void Inventory_Click(object s,RoutedEventArgs e){InventoryPanel.Visibility=Visibility.Visible;SalesPanel.Visibility=Visibility.Collapsed;PageTitle.Text="Inventario";}
 void Sales_Click(object s,RoutedEventArgs e){InventoryPanel.Visibility=Visibility.Collapsed;SalesPanel.Visibility=Visibility.Visible;PageTitle.Text="Ventas rápidas";}
 void SearchBox_TextChanged(object s,System.Windows.Controls.TextChangedEventArgs e){if(IsLoaded)RefreshInventory();}
 void NewProduct_Click(object s,RoutedEventArgs e){var w=new ProductWindow{Owner=this};if(w.ShowDialog()==true)try{db.SaveProduct(w.ProductData);RefreshInventory();}catch(Exception ex){MessageBox.Show("No se pudo guardar. Comprueba que el código sea único. "+ex.Message);}}
 void EditProduct_Click(object s,RoutedEventArgs e){if(ProductsGrid.SelectedItem is not Product p){MessageBox.Show("Selecciona un producto.");return;}var w=new ProductWindow(p){Owner=this};if(w.ShowDialog()==true)try{db.UpdateProduct(w.ProductData);RefreshInventory();}catch(Exception ex){MessageBox.Show("No se pudo actualizar: "+ex.Message);}}
 void DeleteProduct_Click(object s,RoutedEventArgs e){if(ProductsGrid.SelectedItem is not Product p){MessageBox.Show("Selecciona un producto.");return;}if(MessageBox.Show($"¿Eliminar {p.Name}?","Confirmar",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{db.DeleteProduct(p.Id);RefreshInventory();}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void Equivalence_Click(object s,RoutedEventArgs e){if(ProductsGrid.SelectedItem is not Product p){MessageBox.Show("Selecciona primero una refacción.");return;}var brand=Microsoft.VisualBasic.Interaction.InputBox("Marca del catálogo alternativo:","Nueva equivalencia");if(string.IsNullOrWhiteSpace(brand))return;var part=Microsoft.VisualBasic.Interaction.InputBox("Número de parte equivalente:","Nueva equivalencia");if(string.IsNullOrWhiteSpace(part))return;var notes=Microsoft.VisualBasic.Interaction.InputBox("Notas opcionales (modelo, aplicación, etc.):","Nueva equivalencia");try{db.AddEquivalence(p.Id,brand,part,notes);MessageBox.Show("Equivalencia guardada:\n"+string.Join("\n",db.GetEquivalences(p.Id)));}catch(Exception ex){MessageBox.Show("No se pudo guardar la equivalencia: "+ex.Message);}}
 void RefreshInventory(){ProductsGrid.ItemsSource=db.GetProducts(SearchBox.Text);RefreshStatus();}
 void RefreshStatus(){if(IsLoaded&&LowStockText!=null)LowStockText.Text=$"Productos en mínimo: {db.GetLowStock().Count}";}
 void AddSaleItem_Click(object s,RoutedEventArgs e){var p=db.GetProducts(SaleSearchBox.Text).FirstOrDefault();if(p==null){MessageBox.Show("Producto no encontrado.");return;}var line=cart.FirstOrDefault(x=>x.Product.Id==p.Id);if(line!=null)line.Quantity++;else cart.Add(new CartLine(p));CartGrid.Items.Refresh();UpdateTotal();SaleSearchBox.Clear();}
 void UpdateTotal()=>TotalText.Text=$"Total: {cart.Sum(x=>x.Product.Price*x.Quantity):C2}";
 void Checkout_Click(object s,RoutedEventArgs e){try{db.CompleteSale(cart.Select(x=>(x.Product,x.Quantity)).ToList());MessageBox.Show($"Venta registrada: {cart.Sum(x=>x.Product.Price*x.Quantity):C2}");cart.Clear();UpdateTotal();RefreshInventory();}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void CashClose_Click(object s,RoutedEventArgs e){try{var today=DateTime.Today;var summary=db.GetCashSummary(today);var status=summary.IsClosed?"ESTE DÍA YA ESTÁ CERRADO":"CORTE DE CAJA DEL DÍA";var message=$"{status}\nFecha: {today:dd/MM/yyyy}\nVentas registradas: {summary.SalesCount}\nTotal vendido: {summary.Total:C2}";if(summary.IsClosed){MessageBox.Show(message,"Corte de caja",MessageBoxButton.OK,MessageBoxImage.Information);return;}if(MessageBox.Show(message+"\n\n¿Confirmas cerrar la caja? Después del cierre no se podrán registrar más ventas con la fecha de hoy.","Confirmar corte",MessageBoxButton.YesNo,MessageBoxImage.Warning)==MessageBoxResult.Yes){db.CloseCash(today);MessageBox.Show("Corte de caja guardado correctamente.\n"+message,"Corte realizado",MessageBoxButton.OK,MessageBoxImage.Information);}}catch(Exception ex){MessageBox.Show("No se pudo realizar el corte: "+ex.Message);}}
 void Backup_Click(object s,RoutedEventArgs e){var src=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RefaccionariaDesktop","refaccionaria.db");if(!File.Exists(src)){MessageBox.Show("Aún no hay base de datos.");return;}var d=new Microsoft.Win32.SaveFileDialog{FileName="respaldo-refaccionaria.db",Filter="SQLite (*.db)|*.db"};if(d.ShowDialog()==true)File.Copy(src,d.FileName,true);}
 public sealed class CartLine(Product product){public Product Product{get;}=product;public int Quantity{get;set;}=1;}
}